package com.mycompany.projetmedical.dao;

import com.mycompany.projetmedical.util.Bdd;
import com.mycompany.projetmedical.util.Journal;
import java.math.BigDecimal;
import java.sql.*;
import java.time.*;
import java.util.*;

/** JDBC du poste médical. Toute lecture de patient est limitée aux patients suivis par ce médecin. */
public class MedecinDao {
    public record Stats(long rdvJour,long consultationsEnCours,long patientsSuivis){}
    public record Rdv(long id,long patientId,String numero,String patient,LocalDate date,LocalTime debut,LocalTime fin,String statut,String service){}
    public record Patient(long id,String numero,String nom,String email,String telephone,LocalDate naissance,String sexe,boolean dossierOuvert){}
    public record Consultation(long id,long patientId,String patient,String numero,Timestamp date,String motif,String observations,String diagnostic,String conduite,String statut){}
    public record Antecedent(String type,String libelle,String description,LocalDate debut){}
    public record Constante(Timestamp date,String tension,Integer pouls,BigDecimal temperature,BigDecimal poids,BigDecimal taille,Integer spo2,BigDecimal glycemie){}
    public record AnalyseType(int id,String libelle,String unite,String reference){}
    public record Analyse(String type,String statut,Timestamp date,String resultat,String unite,String observations){}
    public record Prescription(long id,Timestamp date,String statut,String notes,String medicament,String dosage,String posologie,String duree,String quantite,String instructions){}

    private boolean autorise(Connection c,long med,long patient)throws SQLException{
        try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM rendez_vous WHERE medecin_id=? AND patient_id=? UNION SELECT 1 FROM consultations WHERE medecin_id=? AND patient_id=? LIMIT 1")){
            p.setLong(1,med);p.setLong(2,patient);p.setLong(3,med);p.setLong(4,patient);try(ResultSet r=p.executeQuery()){return r.next();}
        }
    }
    private void exigerAcces(Connection c,long med,long patient)throws SQLException{if(!autorise(c,med,patient))throw new SQLException("Patient non associé à ce médecin.","42501");}
    public Stats stats(long med)throws SQLException{
        String q="SELECT (SELECT count(*) FROM rendez_vous WHERE medecin_id=? AND date_rdv=CURRENT_DATE AND statut IN ('EN_ATTENTE','CONFIRME')) rdv,(SELECT count(*) FROM consultations WHERE medecin_id=? AND statut='EN_COURS') encours,(SELECT count(DISTINCT patient_id) FROM (SELECT patient_id FROM rendez_vous WHERE medecin_id=? UNION SELECT patient_id FROM consultations WHERE medecin_id=?) x) patients";
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){for(int i=1;i<=4;i++)p.setLong(i,med);try(ResultSet r=p.executeQuery()){r.next();return new Stats(r.getLong(1),r.getLong(2),r.getLong(3));}}
    }
    public List<Consultation> consultationsEnCours(long med)throws SQLException{
        String q="SELECT c.id,c.patient_id,u.prenoms||' '||u.nom patient,p.numero_dossier,c.date_consultation,c.motif,c.observations,c.diagnostic,c.conduite_a_tenir,c.statut FROM consultations c JOIN patients p ON p.utilisateur_id=c.patient_id JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE c.medecin_id=? AND c.statut='EN_COURS' ORDER BY c.date_consultation";
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,med);try(ResultSet r=p.executeQuery()){List<Consultation>a=new ArrayList<>();while(r.next())a.add(new Consultation(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getTimestamp(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10)));return a;}}
    }
    public List<Rdv> rendezVous(long med,LocalDate du,LocalDate au)throws SQLException{
        String q="SELECT r.id,r.patient_id,p.numero_dossier,u.prenoms||' '||u.nom patient,r.date_rdv,r.heure_debut,r.heure_fin,r.statut,s.nom service FROM rendez_vous r JOIN patients p ON p.utilisateur_id=r.patient_id JOIN utilisateurs u ON u.id=p.utilisateur_id LEFT JOIN services s ON s.id=r.service_id WHERE r.medecin_id=? AND r.date_rdv BETWEEN ? AND ? ORDER BY r.date_rdv,r.heure_debut LIMIT 500";
        try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,med);p.setDate(2,java.sql.Date.valueOf(du));p.setDate(3,java.sql.Date.valueOf(au));try(ResultSet r=p.executeQuery()){List<Rdv> a=new ArrayList<>();while(r.next())a.add(new Rdv(r.getLong("id"),r.getLong("patient_id"),r.getString("numero_dossier"),r.getString("patient"),r.getDate("date_rdv").toLocalDate(),r.getTime("heure_debut").toLocalTime(),r.getTime("heure_fin").toLocalTime(),r.getString("statut"),r.getString("service")));return a;}}
    }
    public List<Patient> patients(long med,String query)throws SQLException{
        String q="SELECT p.utilisateur_id,p.numero_dossier,u.prenoms||' '||u.nom patient,u.email,u.telephone,u.date_naissance,u.sexe,EXISTS(SELECT 1 FROM dossiers_medicaux d WHERE d.patient_id=p.utilisateur_id) dossier FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE (EXISTS(SELECT 1 FROM rendez_vous r WHERE r.patient_id=p.utilisateur_id AND r.medecin_id=?) OR EXISTS(SELECT 1 FROM consultations c WHERE c.patient_id=p.utilisateur_id AND c.medecin_id=?)) AND (?='' OR p.numero_dossier ILIKE ? OR u.nom ILIKE ? OR u.prenoms ILIKE ? OR coalesce(u.telephone,'') ILIKE ?) ORDER BY u.nom,u.prenoms LIMIT 200";
        String like="%"+(query==null?"":query.trim())+"%";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,med);p.setLong(2,med);p.setString(3,query==null?"":query.trim());for(int i=4;i<=7;i++)p.setString(i,like);try(ResultSet r=p.executeQuery()){List<Patient>a=new ArrayList<>();while(r.next()){java.sql.Date d=r.getDate("date_naissance");a.add(new Patient(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),d==null?null:d.toLocalDate(),r.getString(7),r.getBoolean(8)));}return a;}}
    }
    public Patient patient(long med,long id)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,id);try(PreparedStatement p=c.prepareStatement("SELECT p.utilisateur_id,p.numero_dossier,u.prenoms||' '||u.nom patient,u.email,u.telephone,u.date_naissance,u.sexe,EXISTS(SELECT 1 FROM dossiers_medicaux d WHERE d.patient_id=p.utilisateur_id) dossier FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE p.utilisateur_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())return null;java.sql.Date d=r.getDate("date_naissance");return new Patient(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),d==null?null:d.toLocalDate(),r.getString(7),r.getBoolean(8));}}}
    }
    public List<Antecedent> antecedents(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);try(PreparedStatement p=c.prepareStatement("SELECT type,libelle,description,date_debut FROM antecedents_medicaux WHERE patient_id=? ORDER BY date_enregistrement DESC")){p.setLong(1,patient);try(ResultSet r=p.executeQuery()){List<Antecedent>a=new ArrayList<>();while(r.next()){java.sql.Date d=r.getDate(4);a.add(new Antecedent(r.getString(1),r.getString(2),r.getString(3),d==null?null:d.toLocalDate()));}return a;}}}
    }
    public List<Consultation> historique(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);try(PreparedStatement p=c.prepareStatement("SELECT c.id,c.patient_id,u.prenoms||' '||u.nom patient,p.numero_dossier,c.date_consultation,c.motif,c.observations,c.diagnostic,c.conduite_a_tenir,c.statut FROM consultations c JOIN patients p ON p.utilisateur_id=c.patient_id JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE c.patient_id=? ORDER BY c.date_consultation DESC LIMIT 100")){p.setLong(1,patient);try(ResultSet r=p.executeQuery()){List<Consultation>a=new ArrayList<>();while(r.next())a.add(new Consultation(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getTimestamp(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10)));return a;}}}
    }
    public List<Constante> constantes(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);try(PreparedStatement p=c.prepareStatement("SELECT date_mesure,tension_arterielle,pouls,temperature_c,poids_kg,taille_cm,spo2,glycemie FROM constantes_vitales WHERE patient_id=? ORDER BY date_mesure DESC LIMIT 100")){p.setLong(1,patient);try(ResultSet r=p.executeQuery()){List<Constante>a=new ArrayList<>();while(r.next())a.add(new Constante(r.getTimestamp(1),r.getString(2),(Integer)r.getObject(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),(Integer)r.getObject(7),r.getBigDecimal(8)));return a;}}}
    }
    public List<Prescription> prescriptions(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);String q="SELECT pr.id,pr.date_prescription,pr.statut,pr.notes,pd.medicament,pd.dosage,pd.posologie,pd.duree,pd.quantite,pd.instructions FROM prescriptions pr LEFT JOIN prescription_details pd ON pd.prescription_id=pr.id WHERE pr.patient_id=? ORDER BY pr.date_prescription DESC LIMIT 200";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,patient);try(ResultSet r=p.executeQuery()){List<Prescription>a=new ArrayList<>();while(r.next())a.add(new Prescription(r.getLong(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10)));return a;}}}
    }
    public List<Analyse> analyses(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);String q="SELECT t.libelle,d.statut,d.date_demande,ra.valeur,ra.unite,ra.observations FROM demandes_analyses d JOIN types_analyses t ON t.id=d.type_analyse_id LEFT JOIN resultats_analyses ra ON ra.demande_id=d.id AND ra.statut='VALIDE' WHERE d.patient_id=? ORDER BY d.date_demande DESC";try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,patient);try(ResultSet r=p.executeQuery()){List<Analyse>a=new ArrayList<>();while(r.next())a.add(new Analyse(r.getString(1),r.getString(2),r.getTimestamp(3),r.getString(4),r.getString(5),r.getString(6)));return a;}}}
    }
    public List<AnalyseType> typesAnalyse()throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("SELECT id,libelle,unite,valeurs_reference FROM types_analyses WHERE actif ORDER BY categorie,libelle");ResultSet r=p.executeQuery()){List<AnalyseType>a=new ArrayList<>();while(r.next())a.add(new AnalyseType(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)));return a;}}
    public long consultationEnCours(long med,long patient)throws SQLException{
        try(Connection c=Bdd.connexion()){exigerAcces(c,med,patient);try(PreparedStatement p=c.prepareStatement("SELECT id FROM consultations WHERE medecin_id=? AND patient_id=? AND statut='EN_COURS' ORDER BY date_consultation DESC LIMIT 1")){p.setLong(1,med);p.setLong(2,patient);try(ResultSet r=p.executeQuery()){return r.next()?r.getLong(1):0;}}}
    }
    public long demarrer(long med,long patient,Long rdv,String motif,String serviceIp)throws SQLException{
        try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{exigerAcces(c,med,patient);try(PreparedStatement d=c.prepareStatement("INSERT INTO dossiers_medicaux(patient_id,modifie_par) VALUES(?,?) ON CONFLICT(patient_id) DO NOTHING")){d.setLong(1,patient);d.setLong(2,med);d.executeUpdate();}
            if(rdv!=null){try(PreparedStatement v=c.prepareStatement("SELECT 1 FROM rendez_vous WHERE id=? AND patient_id=? AND medecin_id=? AND statut IN ('EN_ATTENTE','CONFIRME') FOR UPDATE")){v.setLong(1,rdv);v.setLong(2,patient);v.setLong(3,med);try(ResultSet r=v.executeQuery()){if(!r.next())throw new SQLException("Rendez-vous non autorisé ou déjà traité.","42501");}}}
            String q="INSERT INTO consultations(patient_id,medecin_id,rendez_vous_id,service_id,motif,statut) VALUES(?,?,?,(SELECT service_id FROM utilisateurs WHERE id=?),?,'EN_COURS') RETURNING id";long id;try(PreparedStatement p=c.prepareStatement(q)){p.setLong(1,patient);p.setLong(2,med);if(rdv==null)p.setNull(3,Types.BIGINT);else p.setLong(3,rdv);p.setLong(4,med);p.setString(5,motif);try(ResultSet r=p.executeQuery()){r.next();id=r.getLong(1);}}
            Journal.ecrire(c,med,Journal.CREATION_CONSULTATION,"consultations",id,"Ouverture d'une consultation",true,serviceIp);c.commit();return id;
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    private void verifierConsultation(Connection c,long med,long consultation)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT patient_id FROM consultations WHERE id=? AND medecin_id=? AND statut='EN_COURS' FOR UPDATE")){p.setLong(1,consultation);p.setLong(2,med);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Consultation absente, terminée ou non attribuée à ce médecin.","42501");}}}
    public void enregistrer(long med,long id,String motif,String observations,String diagnostic,String conduite,String ip)throws SQLException{try(Connection c=Bdd.connexion()){verifierConsultation(c,med,id);try(PreparedStatement p=c.prepareStatement("UPDATE consultations SET motif=?,observations=?,diagnostic=?,conduite_a_tenir=?,date_modification=now() WHERE id=? AND medecin_id=? AND statut='EN_COURS'")){p.setString(1,motif);p.setString(2,observations);p.setString(3,diagnostic);p.setString(4,conduite);p.setLong(5,id);p.setLong(6,med);if(p.executeUpdate()!=1)throw new SQLException("Consultation déjà finalisée.","42501");}Journal.ecrire(med,Journal.MODIFICATION_CONSULTATION,"consultations",id,"Mise à jour clinique",true,ip);}}
    public void constante(long med,long consultation,String tension,Integer pouls,BigDecimal temperature,BigDecimal poids,BigDecimal taille,Integer spo2,BigDecimal glycemie,String ip)throws SQLException{try(Connection c=Bdd.connexion()){verifierConsultation(c,med,consultation);String q="INSERT INTO constantes_vitales(consultation_id,patient_id,tension_arterielle,pouls,temperature_c,poids_kg,taille_cm,spo2,glycemie,mesure_par) SELECT c.id,c.patient_id,?,?,?,?,?,?,?,? FROM consultations c WHERE c.id=? AND c.medecin_id=? AND c.statut='EN_COURS'";try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,tension);if(pouls==null)p.setNull(2,Types.INTEGER);else p.setInt(2,pouls);p.setBigDecimal(3,temperature);p.setBigDecimal(4,poids);p.setBigDecimal(5,taille);if(spo2==null)p.setNull(6,Types.INTEGER);else p.setInt(6,spo2);p.setBigDecimal(7,glycemie);p.setLong(8,med);p.setLong(9,consultation);p.setLong(10,med);if(p.executeUpdate()!=1)throw new SQLException("Consultation déjà finalisée.","42501");}Journal.ecrire(med,Journal.ENREGISTREMENT_CONSTANTES,"constantes_vitales",consultation,"Enregistrement des constantes",true,ip);}}
    public void prescription(long med,long consultation,String notes,String medicament,String dosage,String posologie,String duree,String quantite,String instructions,String ip)throws SQLException{try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{verifierConsultation(c,med,consultation);long patient;try(PreparedStatement p=c.prepareStatement("SELECT patient_id FROM consultations WHERE id=?")){p.setLong(1,consultation);try(ResultSet r=p.executeQuery()){r.next();patient=r.getLong(1);}}long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO prescriptions(consultation_id,patient_id,medecin_id,notes) VALUES(?,?,?,?) RETURNING id")){p.setLong(1,consultation);p.setLong(2,patient);p.setLong(3,med);p.setString(4,notes);try(ResultSet r=p.executeQuery()){r.next();id=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO prescription_details(prescription_id,medicament,dosage,posologie,duree,quantite,instructions) VALUES(?,?,?,?,?,?,?)")){p.setLong(1,id);p.setString(2,medicament);p.setString(3,dosage);p.setString(4,posologie);p.setString(5,duree);p.setString(6,quantite);p.setString(7,instructions);p.executeUpdate();}Journal.ecrire(c,med,Journal.CREATION_PRESCRIPTION,"prescriptions",id,"Création de prescription",true,ip);c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    public void demanderAnalyse(long med,long consultation,int type,String priorite,String observations,String ip)throws SQLException{try(Connection c=Bdd.connexion()){String q="INSERT INTO demandes_analyses(patient_id,medecin_id,type_analyse_id,consultation_id,priorite,observations_medecin) SELECT c.patient_id,c.medecin_id,?,c.id,?,? FROM consultations c WHERE c.id=? AND c.medecin_id=? AND c.statut='EN_COURS' AND EXISTS(SELECT 1 FROM types_analyses t WHERE t.id=? AND t.actif)";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,type);p.setString(2,priorite);p.setString(3,observations);p.setLong(4,consultation);p.setLong(5,med);p.setInt(6,type);if(p.executeUpdate()!=1)throw new SQLException("Consultation terminée ou type d’analyse indisponible.","42501");}Journal.ecrire(med,Journal.DEMANDE_ANALYSE,"demandes_analyses",consultation,"Demande d'analyse",true,ip);}}
    public void finaliser(long med,long consultation,String ip)throws SQLException{try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{long patient;try(PreparedStatement p=c.prepareStatement("UPDATE consultations SET statut='TERMINEE',date_modification=now() WHERE id=? AND medecin_id=? AND statut='EN_COURS' RETURNING patient_id,rendez_vous_id")){p.setLong(1,consultation);p.setLong(2,med);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Consultation non finalisable.","42501");patient=r.getLong(1);long rdv=r.getLong(2);if(!r.wasNull())try(PreparedStatement u=c.prepareStatement("UPDATE rendez_vous SET statut='TERMINE',date_modification=now() WHERE id=? AND medecin_id=? AND statut IN ('EN_ATTENTE','CONFIRME')")){u.setLong(1,rdv);u.setLong(2,med);u.executeUpdate();}}}Journal.ecrire(c,med,Journal.MODIFICATION_CONSULTATION,"consultations",consultation,"Consultation finalisée",true,ip);c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
}
